function guessCategory(title) {
    const lower = (title || "").toLowerCase();
    const rules = [
        { keys: ["market", "migros", "carrefour", "a101", "bim", "şok", "sok", "shop", "trendyol", "hepsiburada", "amazon", "akpos"], category: "Alışveriş" },
